//! Post-quantum identity vectors (rfc/PQ-ENCRYPTION.md §11), generated by
//! typescript/test/interops/generate-pq-identity-vectors.ts, checked through the
//! public API. The exact DHIES v3 output is checked in `src/post_quantum.rs`, where
//! the encryption with explicit randomness is reachable.
//!
//! The Rust library has no Hybrid (dilithium_ed25519) key manager: Hybrid identities
//! must be refused with `Error::NotImplemented`, and the vectors that need a Hybrid
//! identity on the receiving side are not run here.

use serde_json::Value;
use vaultysid::{Error, VaultysId};

fn vectors() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/data/pq-identity-vectors.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn unhex(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().unwrap()).unwrap()
}

fn is_hybrid(identity: &Value) -> bool {
    identity["algorithm"] == "dilithium_ed25519"
}

fn load(identity: &Value) -> VaultysId {
    VaultysId::from_secret(&unhex(&identity["secret"]), None).unwrap()
}

#[test]
fn identities() {
    let v = vectors();
    let mut checked = 0;
    for (name, identity) in v["identities"].as_object().unwrap() {
        let secret = unhex(&identity["secret"]);
        let id = unhex(&identity["id"]);
        if is_hybrid(identity) {
            assert!(matches!(
                VaultysId::from_secret(&secret, None),
                Err(Error::NotImplemented(_))
            ));
            assert!(matches!(
                VaultysId::from_id(&id, None, None),
                Err(Error::NotImplemented(_))
            ));
            continue;
        }
        let restored = VaultysId::from_secret(&secret, None).unwrap();
        assert_eq!(restored.id(), id, "{name}: id");
        assert_eq!(
            restored.did(),
            identity["did"].as_str().unwrap(),
            "{name}: DID"
        );
        assert_eq!(restored.get_secret().unwrap(), secret, "{name}: secret");
        let public = VaultysId::from_id(&id, None, None).unwrap();
        assert_eq!(public.id(), id, "{name}: id round trip");
        assert_eq!(public.did(), identity["did"].as_str().unwrap());

        let id_type = identity["type"].as_u64().unwrap() as u8;
        assert_eq!(restored.is_post_quantum(), id_type >= 0x10, "{name}");
        assert_eq!(restored.is_machine(), id_type & 0x0f == 0, "{name}: role");
        assert_eq!(restored.is_person(), id_type & 0x0f == 1, "{name}: role");
        assert_eq!(
            restored.is_organization(),
            id_type & 0x0f == 2,
            "{name}: role"
        );
        if let Some(ek) = identity.get("ek") {
            assert_eq!(public.kem_public_key().unwrap(), unhex(ek), "{name}: k");
            let document = public.did_document();
            assert_eq!(document["keyAgreement"].as_array().unwrap().len(), 2);
        }
        checked += 1;
    }
    assert_eq!(
        checked, 4,
        "3 Dilithium PQ identities and 1 Ed25519 identity"
    );
}

#[test]
fn prf() {
    let v = vectors();
    let mut checked = 0;
    for prf in v["prf"].as_array().unwrap() {
        let identity = &v["identities"][prf["identity"].as_str().unwrap()];
        if is_hybrid(identity) {
            continue;
        }
        let id = load(identity);
        assert_eq!(
            id.hmac(prf["message"].as_str().unwrap()).unwrap(),
            unhex(&prf["hmac"])
        );
        assert_eq!(
            id.key_manager
                .get_secret_hash(&unhex(&prf["secretHashData"]))
                .unwrap(),
            unhex(&prf["secretHash"])
        );
        checked += 1;
    }
    assert_eq!(checked, 3);
}

#[test]
fn signatures() {
    let v = vectors();
    for s in v["signatures"].as_array().unwrap() {
        let identity = &v["identities"][s["identity"].as_str().unwrap()];
        if is_hybrid(identity) {
            continue;
        }
        let id = VaultysId::from_id(&unhex(&identity["id"]), None, None).unwrap();
        // the vector signs SHA-256("VAULTYS_RAW" || message); the Rust key manager
        // verifies raw data
        let digest = unhex(&s["digest"]);
        let mut signature = unhex(&s["signature"]);
        assert!(id.key_manager.verify(&digest, &signature, None));
        signature[100] ^= 1;
        assert!(!id.key_manager.verify(&digest, &signature, None));
    }
}

#[tokio::test]
async fn dhies_v3() {
    let v = vectors();
    let mut checked = 0;
    for c in v["dhiesV3"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let sender = &v["identities"][c["sender"].as_str().unwrap()];
        let recipient = &v["identities"][c["recipient"].as_str().unwrap()];
        if is_hybrid(recipient) {
            continue;
        }
        let recipient_id = load(recipient);
        let sender_id = unhex(&sender["id"]);
        let plaintext = recipient_id
            .dhies_decrypt(&unhex(&c["out"]), &sender_id)
            .await
            .unwrap();
        assert_eq!(plaintext, unhex(&c["plaintext"]), "{name}");

        // Rust to Rust, when the sender can be loaded
        if !is_hybrid(sender) {
            let out = load(sender)
                .dhies_encrypt(&unhex(&c["plaintext"]), &recipient_id.id())
                .await
                .unwrap();
            assert_eq!(out[0], 0x03);
            assert_eq!(out.len(), unhex(&c["out"]).len());
            let back = recipient_id.dhies_decrypt(&out, &sender_id).await.unwrap();
            assert_eq!(back, unhex(&c["plaintext"]), "{name}: Rust round trip");
        }
        checked += 1;
    }
    assert_eq!(checked, 3, "the three cases with a Dilithium recipient");
}

#[tokio::test]
async fn negative_vectors() {
    let v = vectors();
    let negative = &v["negative"];
    for n in negative["ids"].as_array().unwrap() {
        assert!(
            VaultysId::from_id(&unhex(&n["id"]), None, None).is_err(),
            "id {} accepted",
            n["name"]
        );
    }
    for n in negative["secrets"].as_array().unwrap() {
        assert!(
            VaultysId::from_secret(&unhex(&n["secret"]), None).is_err(),
            "secret {} accepted",
            n["name"]
        );
    }
    for n in negative["dhies"].as_array().unwrap() {
        let recipient = load(&v["identities"][n["recipient"].as_str().unwrap()]);
        let sender_id = unhex(&v["identities"][n["sender"].as_str().unwrap()]["id"]);
        assert!(
            recipient
                .dhies_decrypt(&unhex(&n["ciphertext"]), &sender_id)
                .await
                .is_err(),
            "message {} accepted",
            n["name"]
        );
    }
}

#[tokio::test]
async fn post_quantum_identities() {
    use vaultysid::vaultys_id::Algorithm;
    let entropy = [7u8; 32];
    assert!(
        VaultysId::from_entropy_with_alg(&entropy, 0x11, Algorithm::Ed25519)
            .await
            .is_err()
    );
    let pq = VaultysId::from_entropy_with_alg(&entropy, 0x10, Algorithm::Dilithium)
        .await
        .unwrap();
    assert!(pq.is_post_quantum() && pq.is_machine() && !pq.is_person());
    assert_eq!(pq.id().len(), 3827);
    let classical = VaultysId::from_entropy_with_alg(&entropy, 0x00, Algorithm::Dilithium)
        .await
        .unwrap();
    assert!(!classical.is_post_quantum() && classical.kem_public_key().is_none());
    assert_ne!(pq.did()[14..], classical.did()[14..]);
    // the PRF key replaces the X25519 secret
    assert_ne!(pq.hmac("file").unwrap(), classical.hmac("file").unwrap());
    // reserved types
    for reserved in [0x13u8, 0x14] {
        let mut id = pq.id();
        id[0] = reserved;
        assert!(VaultysId::from_id(&id, None, None).is_err());
    }
    // a public PQ identity cannot decrypt
    let out = classical.dhies_encrypt(b"m", &pq.id()).await.unwrap();
    assert_eq!(out[0], 0x03);
    let public = VaultysId::from_id(&pq.id(), None, None).unwrap();
    assert!(public.dhies_decrypt(&out, &classical.id()).await.is_err());
    assert_eq!(pq.dhies_decrypt(&out, &classical.id()).await.unwrap(), b"m");
}
